const fmt=(s,opts={day:'numeric',month:'short'})=>s?new Date(`${s}T12:00:00`).toLocaleDateString('fr-FR',opts):'Date à définir';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=()=>{try{const x=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(x)?x:[]}catch{return []}};
