const reminderMinutes=()=>Math.max(0,Math.min(1440,Number(localStorage.getItem(REMINDER_KEY)??30)||0));
const page=document.body.dataset.page; const app=$('#app');
function toast(msg){let t=$('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.append(t)}t.textContent=msg;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),2800)}
const THEME_KEY='doucement.theme';
function applyTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem(THEME_KEY,theme)}catch{};$$('[data-theme-toggle],#themeToggle').forEach(b=>{b.textContent=theme==='dark'?'☀️':'🌙';b.title=theme==='dark'?'Passer au mode clair':'Passer au mode sombre';b.setAttribute('aria-label',b.title)})}
