const NAV_LINKS=[['accueil.html','⌂','Accueil','home'],['projet.html','＋','Créer un projet','project'],['planning.html','▦','Planning','planning'],['historique.html','↻','Historique','history'],['voyages.html','⌖','Voyages & escapades',''],['souvenirs.html','♡','Souvenirs',''],['idees.html','✧','Nos idées',''],['budget.html','€','Budget partagé',''],['journee.html','◷','Journée spéciale',''],['messages.html','✉','Messages à ouvrir',''],['stats.html','▥','Statistiques','']];
